// <work-map> — THE maps reinvention: the map IS a SPATIAL VIEW OVER A QUERY, not a
// hand-fed GeoJSON blob. Points / regions come from query ROWS — lat/lon (and an
// optional value) are columns of a WbQueryResult. Spatial filtering and
// aggregation belong IN the engine (SQL: GROUP BY region, WHERE lon BETWEEN …),
// never in JS. The element is a thin, themed, pan/zoom viewport over the result.
//
// Composition-as-source: the map carries its data + query as source. Reach
// compute ONLY through the src/data layer (getEngine) — exactly the pattern
// <work-table> uses, generalized to the shared DuckDB engine. One engine, three
// surfaces: a table, a chart, and a map can all read the SAME registered source.
//
// Re-based onto Lit: render() returns the Lit shell (the stage + chrome + the
// pre-built SVG markup, dropped in via unsafeHTML — the drawing/projection code is
// ours); pan/zoom/select wiring lives in Lit's updated() hook. The _load
// single-flight + stable inline auto-name + whenRegistered/register plumbing is
// unchanged.
//
// Base layer (zero-dep, framework-agnostic): standalone, the map draws an
// ABSTRACT themed projection — points/regions projected to SVG with a chosen
// projection + a graticule, plus an optional slotted/inline vector world outline.
// Works with NO tile provider and NO network. Tile/basemap PIXELS are a keyed
// exception reached through the Host seam (this.host) when configured — see
// _tileLayerHint(); we never hard-depend on a tile CDN.
//
// Usage (inline points, declared lat/lon/value columns):
//   <work-map rows='[{"city":"Oslo","lat":59.9,"lon":10.7,"pop":700}]'
//           lat="lat" lon="lon" value="pop" mode="points"></work-map>
//
// Usage (register elsewhere, query a named source, aggregate in the engine):
//   <work-map src-name="quakes"
//           query="SELECT region, avg(lat) AS lat, avg(lon) AS lon, count(*) AS n
//                   FROM quakes GROUP BY region"
//           lat="lat" lon="lon" value="n" label="region" mode="choropleth"></work-map>
//
// Attributes:
//   rows        inline JSON array of row objects (auto-registers a source)
//   csv         inline CSV text (header row)
//   src-name    name of a source registered via getEngine().register(...)
//   query       full SQL to run (overrides the default SELECT * over src-name)
//   geojson     inline GeoJSON FeatureCollection (regions for choropleth);
//               may also be a slotted <script type="application/geo+json">
//   lat / lon   column names holding latitude / longitude (default "lat"/"lon")
//   value       column name driving size (points) / fill (choropleth)
//   label       column name for the feature label (tooltip / select detail)
//   key         column name matched to a GeoJSON feature property (choropleth)
//   geo-key     GeoJSON feature property matched to `key` (default: same as key)
//   projection  mercator | equirectangular   (default mercator)
//   mode        points | heat | choropleth    (the spatial-view variant)
//   variant     card | bare    (visual shell)
//   tiles       a tile-layer id reached via Host (e.g. "osm"); standalone if unset
//   engine      auto | maplibre | floor   (render tier — see below)
//
// TWO render tiers behind ONE public API (attrs / events / data path identical):
//   • FLOOR — the zero-dependency SVG projection above (points/heat/choropleth),
//     themed entirely from --work-*. The guaranteed render; never blocks on a net.
//   • POWERED — MapLibre GL (./maplibre-tier.js), lazy-loaded from a CDN ESM at
//     runtime (overridable via window.__WB_MAPLIBRE__). Renders the SAME features
//     from the SAME engine query — only the drawing/basemap changes. Real tiles
//     route through the Host (`this.host`, "tiles" cap); with no Host it draws a
//     token-themed blank/vector style (NO hardcoded CDN tile URL).
//   The tier resolves per-load: `engine="maplibre"|"floor"` attr or
//   window.__WB_MAP_ENGINE__ force it; default "auto" prefers MapLibre and falls
//   back to the floor instantly if the lazy import fails (offline / blocked).
//
// Events:
//   work-map-ready    { detail: { columns, types, engine, mode } }
//   work-map-query    { detail: { sql, rowCount, engine } }   on every (re)query
//   work-feature-select { detail: { feature, index } }        feature = row object
import { WbElement, html, css, define } from "../../core/element.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { getEngine } from "../../data/index.js";
import { project, unproject, bounds } from "./projection.js";
import {
  loadMaplibre, loadMaplibreCss, readTokens, buildStyle,
  featuresToGeoJSON, addDataLayers,
} from "./maplibre-tier.js";

const VARIANTS = defineVariants({
  mode: { options: ["points", "heat", "choropleth"], default: "points" },
  variant: { options: ["card", "bare"], default: "card" },
  projection: { options: ["mercator", "equirectangular"], default: "mercator" },
});

let _autoId = 0;

export class WbMap extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "rows", "csv", "src-name", "query",
    "lat", "lon", "value", "label", "key", "geo-key", "geojson", "tiles",
    "engine",   // tier override: auto (default, prefer MapLibre) | maplibre | floor
  ];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .shell { position: relative; border: 1px solid var(--work-border);
      border-radius: var(--work-radius); background: var(--work-surface);
      overflow: hidden; box-shadow: var(--work-shadow-sm); }
    :host([variant="bare"]) .shell { border: none; box-shadow: none; background: transparent; }

    .stage { position: relative; width: 100%;
      height: var(--work-map-h, 460px); cursor: grab;
      background:
        radial-gradient(120% 120% at 50% -10%, var(--work-surface) 0%, var(--work-surface-soft) 100%); }
    .stage.dragging { cursor: grabbing; }
    svg { display: block; width: 100%; height: 100%; touch-action: none; user-select: none; }

    /* the POWERED tier host (MapLibre GL canvas). When it carries a child the
       floor SVG is declaratively hidden — no imperative show/hide race. */
    .gl { position: absolute; inset: 0; }
    .gl:empty { display: none; }
    .stage:has(.gl > *) > svg { visibility: hidden; }
    .gl .maplibregl-map { width: 100%; height: 100%; }

    /* the abstract themed basemap */
    .graticule { stroke: var(--work-border); stroke-width: var(--work-map-grid-w, 1); fill: none; opacity: .55; }
    .frame { stroke: var(--work-border-strong); stroke-width: 1; fill: none; opacity: .7; }
    .land { fill: var(--work-surface-soft); stroke: var(--work-border-strong); stroke-width: 1; opacity: .9; }

    /* choropleth regions (bound to query rows) */
    .region { stroke: var(--work-surface); stroke-width: 1; cursor: pointer;
      transition: filter var(--work-dur, .14s) var(--work-ease, ease); }
    .region:hover { filter: brightness(1.08); }
    .region[aria-selected="true"] { stroke: var(--work-fg); stroke-width: 2; }

    /* points / heat */
    .pt { fill: var(--work-brand); fill-opacity: .82; stroke: var(--work-surface); stroke-width: 1.2;
      cursor: pointer; transition: fill-opacity var(--work-dur,.14s) var(--work-ease,ease); }
    .pt:hover { fill-opacity: 1; }
    .pt[aria-selected="true"] { stroke: var(--work-fg); stroke-width: 2; }
    .heat { fill: var(--work-brand); }

    /* chrome */
    .toolbar { position: absolute; top: var(--work-space-2); left: var(--work-space-2);
      display: flex; align-items: center; gap: var(--work-space-2); z-index: 2; }
    .badge { display: inline-flex; align-items: center; gap: var(--work-space-1);
      font: 600 10px var(--work-font-mono); letter-spacing: .12em; text-transform: uppercase;
      color: var(--work-fg-muted); background: var(--work-surface); border: 1px solid var(--work-border);
      border-radius: var(--work-radius-pill); padding: var(--work-space-3px) var(--work-space-9px); box-shadow: var(--work-shadow-sm); }
    .engine .dot { width: 7px; height: 7px; border-radius: var(--work-radius-pill); background: var(--work-brand);
      box-shadow: 0 0 0 3px var(--work-brand-soft); }
    .engine[data-tier="memory"] .dot { background: var(--work-warn); box-shadow: 0 0 0 var(--work-space-3px) var(--work-warn-glow); }
    .engine[data-tier="error"] .dot { background: var(--work-err); box-shadow: none; }

    .zoom { position: absolute; top: var(--work-space-2); right: var(--work-space-2);
      display: flex; flex-direction: column; z-index: 2; box-shadow: var(--work-shadow-sm);
      border-radius: var(--work-radius-sm); overflow: hidden; border: 1px solid var(--work-border); }
    .zoom button { font: 600 15px var(--work-font-mono); width: 30px; height: 30px; line-height: 1;
      border: none; background: var(--work-surface); color: var(--work-fg); cursor: pointer; }
    .zoom button + button { border-top: 1px solid var(--work-border); }
    .zoom button:hover { background: var(--work-surface-soft); }

    .legend { position: absolute; bottom: var(--work-space-2); left: var(--work-space-2); z-index: 2;
      display: flex; align-items: center; gap: var(--work-space-2);
      font: 500 11px var(--work-font-mono); color: var(--work-fg-muted);
      background: var(--work-surface); border: 1px solid var(--work-border);
      border-radius: var(--work-radius-sm); padding: var(--work-space-1) var(--work-space-2); box-shadow: var(--work-shadow-sm); }
    .ramp { width: 96px; height: 8px; border-radius: var(--work-radius-pill);
      background: linear-gradient(90deg, var(--work-brand-soft), var(--work-brand)); }

    .tip { position: absolute; z-index: 3; pointer-events: none; transform: translate(-50%, -120%);
      background: var(--work-fg); color: var(--work-surface); font: 600 11px var(--work-font-mono);
      padding: var(--work-space-1) var(--work-space-2); border-radius: var(--work-radius-sm); white-space: nowrap;
      box-shadow: var(--work-shadow); opacity: 0; transition: opacity var(--work-dur,.14s); }
    .tip.show { opacity: 1; }

    .foot { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-top: 1px solid var(--work-border);
      font-size: var(--work-text-sm); color: var(--work-fg-subtle); }
    .note { color: var(--work-fg-subtle); }
    .grow { flex: 1; }
    .empty { padding: var(--work-space-5); text-align: center; color: var(--work-fg-muted); font-size: var(--work-text-sm); }
  `;

  connectedCallback() {
    if (this._init == null) {
      this._init = true;
      this._engine = getEngine();
      this._result = null;
      this._tier = "memory";
      this._error = null;
      this._busy = true;
      this._sel = null;             // selected feature index
      this._view = { k: 1, x: 0, y: 0 }; // zoom factor + pan offset (plane units)
      this._features = [];          // projected, render-ready
      this._captureSource();
      this._captureGeojson();
    }
    super.connectedCallback();
    this._load();
    // The FLOOR re-themes automatically (token-driven CSS). The POWERED tier paints
    // onto a WebGL canvas where CSS tokens don't reach, so a theme flip must re-read
    // tokens + rebuild MapLibre's paint. Observe the documentElement theme attr and
    // redraw the powered tier when it changes (no-op when on the floor).
    if (typeof MutationObserver !== "undefined" && !this._themeObs) {
      this._themeObs = new MutationObserver(() => { if (this._map) { this._teardownPowered(); this._drawPowered(); } });
      this._themeObs.observe(document.documentElement, { attributes: true, attributeFilter: ["data-work-theme", "class"] });
    }
  }

  disconnectedCallback() {
    this._teardownPowered();
    if (this._themeObs) { this._themeObs.disconnect(); this._themeObs = null; }
    super.disconnectedCallback();
  }

  _captureSource() {
    this._srcName = this.attr("src-name");
    if (!this._srcName) {
      const rowsAttr = this.attr("rows");
      const csvAttr = this.attr("csv");
      if (!this._autoName) this._autoName = `work_geo_${++_autoId}`;
      this._srcName = this._autoName;
      if (rowsAttr) this._pendingSource = { json: rowsAttr };
      else if (csvAttr) this._pendingSource = { csv: csvAttr };
      else {
        const text = this.textContent.trim();
        if (text.startsWith("[")) this._pendingSource = { json: text };
        else if (text.includes(",") && text.includes("\n")) this._pendingSource = { csv: text };
      }
    }
  }

  _captureGeojson() {
    // inline attr wins; else a slotted <script type="application/geo+json">.
    const inline = this.attr("geojson");
    if (inline) { this._geojson = safeJson(inline); return; }
    const slot = this.querySelector('script[type="application/geo+json"], script[type="application/json"][data-geojson]');
    this._geojson = slot ? safeJson(slot.textContent) : null;
  }

  attributeChangedCallback(name, old, val) {
    super.attributeChangedCallback(name, old, val);
    if (!this._init) return;
    if (name === "rows" || name === "csv" || name === "src-name" || name === "query") {
      this._pendingSource = null;
      this._captureSource();
      this._load();
    } else if (name === "geojson") {
      this._captureGeojson();
      this._rebuild();
      this.requestUpdate();
    } else {
      // lat/lon/value/label/key/mode/projection/variant — re-derive features
      this._rebuild();
      this.requestUpdate();
    }
  }

  async _load() {
    if (this._loading) { this._loadAgain = true; return; }
    this._loading = true;
    do {
      this._loadAgain = false;
      this._busy = true; this._error = null; this.requestUpdate();
      try {
        if (this._pendingSource) await this._engine.register(this._srcName, this._pendingSource);
        else if (this.hasAttribute("src-name")) await this._engine.whenRegistered(this._srcName);
        await this._run();
      } catch (e) {
        this._error = String((e && e.message) || e);
        this._tier = "error";
      }
      this._busy = false;
      this._rebuild();
      if (!this._fitted && this._features.length) { this._fit(); this._fitted = true; }
      this.requestUpdate();
      this._emit("work-map-ready", {
        columns: this._result?.columns || [], types: this._result?.types || [],
        engine: this._tier, mode: this.variant("mode"),
      });
    } while (this._loadAgain);
    this._loading = false;
  }

  async _run() {
    const sql = this._buildSql();
    this._result = await this._engine.query(sql);
    this._tier = this._result.engine || this._engine.provider();
    this._emit("work-map-query", { sql, rowCount: this._result.rowCount, engine: this._tier });
  }

  /** Spatial filtering/aggregation lives in SQL — we just pick the source/query. */
  _buildSql() {
    const base = this.attr("query");
    if (base) return base.replace(/;$/, "");
    return `SELECT * FROM ${ident(this._srcName)}`;
  }

  variant(name) {
    const def = VARIANTS[name];
    const v = this.getAttribute(name);
    return def && def.options.includes(v) ? v : def?.default;
  }

  // ── map {columns, rows[][], types} -> features ──────────────────────────────
  _rebuild() {
    this._features = [];
    const r = this._result;
    if (!r || !r.columns.length) return;
    const proj = this.variant("projection");
    const mode = this.variant("mode");
    const latC = colIdx(r, this.attr("lat", "lat"));
    const lonC = colIdx(r, this.attr("lon", "lon"));
    const valC = colIdx(r, this.attr("value"));
    const labC = colIdx(r, this.attr("label"));
    const keyC = colIdx(r, this.attr("key"));

    // value range (engine produced the numbers; we only scale to tokens here)
    let vMin = Infinity, vMax = -Infinity;
    if (valC >= 0) for (const row of r.rows) {
      const v = Number(row[valC]);
      if (!Number.isNaN(v)) { if (v < vMin) vMin = v; if (v > vMax) vMax = v; }
    }
    if (!isFinite(vMin)) { vMin = 0; vMax = 1; }
    this._vRange = [vMin, vMax];

    const rowObj = (i) => { const o = {}; r.columns.forEach((c, j) => (o[c] = r.rows[i][j])); return o; };

    if (mode === "choropleth" && this._geojson) {
      // True polygon choropleth: bind region ROWS to GeoJSON features by key.
      const geoKeyProp = this.attr("geo-key", this.attr("key"));
      const byKey = new Map();
      r.rows.forEach((row, i) => {
        const k = keyC >= 0 ? row[keyC] : (labC >= 0 ? row[labC] : i);
        byKey.set(String(k), { i, v: valC >= 0 ? Number(row[valC]) : null });
      });
      for (const f of (this._geojson.features || [])) {
        const k = geoKeyProp ? f.properties?.[geoKeyProp] : null;
        const hit = byKey.get(String(k));
        const rings = geometryToRings(f.geometry, proj);
        if (!rings.length) continue;
        this._features.push({
          kind: "region", rings,
          v: hit ? hit.v : null, i: hit ? hit.i : -1,
          row: hit ? rowObj(hit.i) : { ...f.properties },
        });
      }
      return;
    }

    // points / heat (and choropleth fallback = graduated bubbles at row coords)
    if (latC < 0 || lonC < 0) return;
    r.rows.forEach((row, i) => {
      const lat = Number(row[latC]), lon = Number(row[lonC]);
      if (Number.isNaN(lat) || Number.isNaN(lon)) return;
      const [x, y] = project(lon, lat, proj);
      this._features.push({
        kind: "point", x, y, lat, lon,
        v: valC >= 0 ? Number(row[valC]) : null,
        label: labC >= 0 ? row[labC] : null,
        i, row: rowObj(i),
      });
    });
  }

  // ── view transform (pan/zoom over the normalized plane) ─────────────────────
  _fit() {
    // Fit the data (or whole world) into the unit plane, then center it.
    const pts = this._features.flatMap((f) => f.kind === "point" ? [[f.lon, f.lat]] :
      f.rings.flatMap((rg) => rg)); // region rings already in plane coords below
    if (this.variant("mode") === "choropleth" && this._geojson) {
      // rings are already plane coords; compute bbox directly
      let minX = 1, minY = 1, maxX = 0, maxY = 0;
      for (const f of this._features) for (const rg of f.rings) for (const [x, y] of rg) {
        if (x < minX) minX = x; if (y < minY) minY = y;
        if (x > maxX) maxX = x; if (y > maxY) maxY = y;
      }
      if (maxX <= minX) return;
      this._applyFit(minX, minY, maxX, maxY);
      return;
    }
    if (pts.length) {
      const b = bounds(pts, this.variant("projection"));
      this._applyFit(b.minX, b.minY, b.maxX, b.maxY);
    }
  }

  _applyFit(minX, minY, maxX, maxY) {
    const padX = (maxX - minX) * 0.12 + 0.02, padY = (maxY - minY) * 0.12 + 0.02;
    minX -= padX; maxX += padX; minY -= padY; maxY += padY;
    const w = Math.max(maxX - minX, 1e-3), h = Math.max(maxY - minY, 1e-3);
    const k = Math.min(1 / w, 1 / h);
    this._view = { k, x: -minX * k, y: -minY * k };
  }

  // ── render ──────────────────────────────────────────────────────────────────
  render() {
    const mode = this.variant("mode");
    const tierText = this._busy ? "querying…" : this._error ? "engine error" :
      this._tier === "runtime" ? "engine: runtime DuckDB" :
      this._tier === "duckdb-wasm" ? "engine: DuckDB-wasm (in-browser)" :
      "engine: in-JS (offline)";
    const baseText = this.attr("tiles")
      ? `basemap: ${esc(this.attr("tiles"))} (via Host)` : "basemap: abstract (standalone)";

    let body;
    if (this._busy && !this._result) body = `<div class="stage"><div class="empty">Loading…</div></div>`;
    else if (this._error) body = `<div class="stage"><div class="empty">${esc(this._error)}</div></div>`;
    else if (!this._features.length) body = `<div class="stage"><div class="empty">No spatial rows.</div></div>`;
    else body = this._renderStage(mode);

    const shell = `<div class="shell">
      ${body}
      <div class="foot">
        <span class="note">${esc(tierText)}</span>
        <span class="note">· ${esc(baseText)}</span>
        ${this._result ? `<span class="grow"></span><span class="note">${this._features.length.toLocaleString()} features</span>` : ""}
      </div>
    </div>`;
    return html`${unsafeHTML(shell)}`;
  }

  _renderStage(mode) {
    const VB = 1000; // viewBox px per plane unit
    const { k, x, y } = this._view;
    // SVG transform: plane[0..1] -> screen, with view pan/zoom.
    const t = `translate(${x * VB} ${y * VB}) scale(${k})`;
    const grat = this._graticule(VB);
    const land = this._landPaths(t, VB);
    const layer = mode === "choropleth" && this._geojson
      ? this._renderRegions(VB) : mode === "heat" ? this._renderHeat(VB)
      : mode === "choropleth" ? this._renderBubbles(VB) : this._renderPoints(VB);

    const legend = (this.attr("value") != null && mode !== "points")
      ? `<div class="legend"><span>${esc(this.attr("value"))}</span><span class="ramp"></span>
           <span>${fmtNum(this._vRange[1])}</span></div>` : "";

    return `<div class="stage">
      <div class="toolbar">
        <span class="badge engine" data-tier="${this._error ? "error" : this._tier}"><span class="dot"></span>${esc(mode)}</span>
      </div>
      <div class="zoom"><button data-z="in" aria-label="zoom in">+</button><button data-z="out" aria-label="zoom out">−</button></div>
      ${legend}
      <div class="tip" id="tip"></div>
      <svg viewBox="0 0 ${VB} ${VB}" preserveAspectRatio="xMidYMid slice">
        <g class="basemap" transform="${t}">
          ${grat}
          ${land}
        </g>
        <g class="data" transform="${t}">
          ${layer}
        </g>
      </svg>
      <div class="gl" part="gl"></div>
    </div>`;
  }

  _graticule(VB) {
    // lon/lat grid + a frame, in plane coords (the abstract themed basemap).
    const proj = this.variant("projection");
    const lines = [];
    for (let lon = -180; lon <= 180; lon += 30) {
      const seg = [];
      for (let lat = -85; lat <= 85; lat += 5) { const [px, py] = project(lon, lat, proj); seg.push(`${px * VB},${py * VB}`); }
      lines.push(`<polyline class="graticule" points="${seg.join(" ")}" />`);
    }
    for (let lat = -60; lat <= 60; lat += 30) {
      const seg = [];
      for (let lon = -180; lon <= 180; lon += 10) { const [px, py] = project(lon, lat, proj); seg.push(`${px * VB},${py * VB}`); }
      lines.push(`<polyline class="graticule" points="${seg.join(" ")}" />`);
    }
    const [x0, y0] = project(-180, 85, proj), [x1, y1] = project(180, -85, proj);
    lines.push(`<rect class="frame" x="${x0 * VB}" y="${y0 * VB}" width="${(x1 - x0) * VB}" height="${(y1 - y0) * VB}" />`);
    return lines.join("");
  }

  _landPaths(_t, VB) {
    // Optional slotted/inline world outline (when NOT used as choropleth source).
    if (this.variant("mode") === "choropleth" && this._geojson) return "";
    if (!this._geojson) return "";
    const proj = this.variant("projection");
    let d = "";
    for (const f of (this._geojson.features || [])) {
      for (const rg of geometryToRings(f.geometry, proj)) {
        d += "M" + rg.map(([px, py]) => `${(px * VB).toFixed(1)} ${(py * VB).toFixed(1)}`).join("L") + "Z";
      }
    }
    return d ? `<path class="land" d="${d}" />` : "";
  }

  _renderPoints(VB) {
    const r = 6 / Math.max(this._view.k, 1); // keep markers readable while zoomed
    return this._features.map((f) => {
      const rr = f.v != null ? r * (0.5 + this._scale(f.v)) : r;
      return `<circle class="pt" data-i="${f.i}" cx="${(f.x * VB).toFixed(1)}" cy="${(f.y * VB).toFixed(1)}"
        r="${rr.toFixed(2)}" ${this._sel === f.i ? 'aria-selected="true"' : ""} />`;
    }).join("");
  }

  _renderBubbles(VB) {
    // choropleth WITHOUT GeoJSON = graduated proportional bubbles (the standalone
    // floor; the engine still did the GROUP BY that produced these rows).
    const base = 26 / Math.max(this._view.k, 1);
    return this._features
      .slice().sort((a, b) => (b.v || 0) - (a.v || 0))
      .map((f) => {
        const rr = base * (0.25 + this._scale(f.v));
        const fill = this._fillFor(f.v);
        return `<circle class="pt" style="fill:${fill};fill-opacity:.62" data-i="${f.i}"
          cx="${(f.x * VB).toFixed(1)}" cy="${(f.y * VB).toFixed(1)}" r="${rr.toFixed(2)}"
          ${this._sel === f.i ? 'aria-selected="true"' : ""} />`;
      }).join("");
  }

  _renderHeat(VB) {
    // Lightweight heat: stacked translucent radial blooms (no shader, no dep).
    const base = 40 / Math.max(this._view.k, 1);
    return this._features.map((f) => {
      const rr = base * (0.4 + this._scale(f.v));
      const op = (0.12 + 0.5 * this._scale(f.v)).toFixed(2);
      return `<circle class="heat" data-i="${f.i}" cx="${(f.x * VB).toFixed(1)}" cy="${(f.y * VB).toFixed(1)}"
        r="${rr.toFixed(1)}" style="fill-opacity:${op}" />`;
    }).join("");
  }

  _renderRegions(VB) {
    return this._features.map((f) => {
      const d = f.rings.map((rg) => "M" + rg.map(([px, py]) => `${(px * VB).toFixed(1)} ${(py * VB).toFixed(1)}`).join("L") + "Z").join("");
      const fill = f.v == null ? "var(--work-surface-soft)" : this._fillFor(f.v);
      return `<path class="region" data-i="${f.i}" d="${d}" style="fill:${fill}"
        ${this._sel === f.i ? 'aria-selected="true"' : ""} />`;
    }).join("");
  }

  /** Normalize a value into [0..1] across the engine-computed range. */
  _scale(v) {
    if (v == null || Number.isNaN(+v)) return 0.4;
    const [lo, hi] = this._vRange;
    if (hi <= lo) return 0.6;
    return Math.sqrt((+v - lo) / (hi - lo)); // sqrt -> area-fair point sizing
  }

  /** Token-only choropleth fill: blend toward --work-brand by value (via opacity). */
  _fillFor(v) {
    const t = this._scale(v);
    // color-mix keeps everything token-driven; falls back to brand if unsupported.
    return `color-mix(in srgb, var(--work-brand) ${Math.round(15 + t * 85)}%, var(--work-surface-soft))`;
  }

  /** Documented Host path for real basemap PIXELS (a keyed exception). */
  _tileLayerHint() {
    const id = this.attr("tiles");
    if (!id || !this.host?.available?.("tiles")) return null;
    // A Host that exposes "tiles" brokers PMTiles/tile requests; the element would
    // request tile URLs through this.host.request("/maps/tiles", …) and draw them
    // UNDER the data layer. Standalone (no tiles attr / no Host cap) we never reach
    // a CDN — the abstract projection above is the basemap. (Wiring lands with the
    // PMTiles broker; the data binding is the reinvention, not a Leaflet clone.)
    return id;
  }

  // ── tier resolution (mirrors wb-chart's _tierChoice) ──────────────────────────
  // floor (zero-dep SVG projection) vs maplibre (MapLibre GL).
  //   - attribute engine="floor" | "maplibre" forces it (the gate drives this)
  //   - window.__WB_MAP_ENGINE__ = "floor" | "maplibre" is the host opt-out
  //   - default "auto": prefer MapLibre when it loads, fall back to the floor.
  _tierChoice() {
    const attr = this.attr("engine");
    if (attr === "floor" || attr === "maplibre") return attr;
    const host = typeof window !== "undefined" && window.__WB_MAP_ENGINE__;
    if (host === "floor" || host === "maplibre") return host;
    return "auto";
  }

  /**
   * Resolve a MapLibre tile source spec through the Host (a keyed exception). With
   * no Host "tiles" capability we return null → MapLibre renders the token-themed
   * blank style (NO hardcoded CDN tile URL — keeps the offline/wasm gate green).
   */
  _resolveTileSource() {
    const id = this.attr("tiles");
    if (!id || !this.host?.available?.("tiles")) return null;
    try { return this.host.tileSource?.(id) || null; } catch { return null; }
  }

  // The POWERED tier — MapLibre GL, lazy-loaded. On success it draws the SAME
  // features into the .gl host (the floor SVG is hidden declaratively by CSS). On
  // failure (network-blocked / load error) it leaves the floor in place — forced
  // engine="maplibre" still degrades gracefully; the floor IS the guaranteed
  // render (the wasm/floor gate proves this).
  async _drawPowered() {
    const gl = this.shadowRoot && this.shadowRoot.querySelector(".gl");
    if (!gl || !this._features.length) return;
    const token = (this._glToken = (this._glToken || 0) + 1);
    let ml;
    try { ml = await loadMaplibre(); }
    catch { return; /* floor already drawn — graceful degrade */ }
    if (token !== this._glToken || !this.isConnected) return;
    this._ML = ml;

    // gate-b: adopt MapLibre's stylesheet into the SHADOW root (constructable
    // sheet), never document.head. Best-effort.
    try {
      if (!this._mlSheet) {
        const cssText = await loadMaplibreCss();
        if (cssText) {
          this._mlSheet = new CSSStyleSheet();
          this._mlSheet.replaceSync(cssText);
          this.shadowRoot.adoptedStyleSheets = [...this.shadowRoot.adoptedStyleSheets, this._mlSheet];
        }
      }
    } catch {}
    if (token !== this._glToken) return;

    const tk = readTokens(this);
    const projKind = this.variant("projection");
    const geojson = featuresToGeoJSON(this._features, unproject, projKind);
    const tileSource = this._resolveTileSource();

    if (!this._map) {
      try {
        this._map = new ml.Map({
          container: gl,
          style: buildStyle(tk, tileSource),
          attributionControl: false,
          interactive: true,
        });
      } catch (e) { this._map = null; return; }
      const onReady = () => {
        if (token !== this._glToken) { try { this._map.remove(); } catch {} this._map = null; return; }
        // the .gl container only gets its real box after shadow layout — resize so
        // MapLibre's canvas matches the stage before we fit the data bounds.
        try { this._map.resize(); } catch {}
        addDataLayers(this._map, this.variant("mode"), geojson, this._features, tk);
        this._fitMapLibre(geojson, projKind);
        this._wireMapLibreSelect();
        this._emit("work-map-engine", { engine: "maplibre" });
      };
      if (this._map.loaded && this._map.loaded()) onReady();
      else this._map.on("load", onReady);
    } else {
      this._map.setStyle(buildStyle(tk, tileSource));
      const reAdd = () => {
        addDataLayers(this._map, this.variant("mode"), geojson, this._features, tk);
        this._wireMapLibreSelect();
      };
      if (this._map.isStyleLoaded && this._map.isStyleLoaded()) reAdd();
      else this._map.once("styledata", reAdd);
    }
  }

  // Fit the MapLibre viewport to the data's lon/lat bbox (mirrors floor _fit).
  _fitMapLibre(geojson, projKind) {
    let minLon = 180, minLat = 90, maxLon = -180, maxLat = -90, any = false;
    const eat = (lon, lat) => { any = true;
      if (lon < minLon) minLon = lon; if (lon > maxLon) maxLon = lon;
      if (lat < minLat) minLat = lat; if (lat > maxLat) maxLat = lat; };
    for (const f of geojson.features) {
      if (f.geometry.type === "Point") eat(...f.geometry.coordinates);
      else if (f.geometry.type === "Polygon") for (const ring of f.geometry.coordinates) for (const [lo, la] of ring) eat(lo, la);
    }
    if (!any) return;
    try { this._map.fitBounds([[minLon, minLat], [maxLon, maxLat]], { padding: 36, duration: 0, maxZoom: 6 }); } catch {}
  }

  // Forward MapLibre feature clicks to the SAME work-feature-select contract.
  _wireMapLibreSelect() {
    if (!this._map || this._mlWired) return;
    this._mlWired = true;
    for (const layer of ["wb-points", "wb-regions"]) {
      this._map.on("click", layer, (e) => {
        const feat = e.features && e.features[0];
        if (!feat) return;
        const fi = feat.properties?._fi;
        const ff = this._features.find((x) => x.i === fi);
        this._sel = fi;
        if (ff) this._emit("work-feature-select", { feature: ff.row, index: fi });
      });
      this._map.on("mouseenter", layer, () => { this._map.getCanvas().style.cursor = "pointer"; });
      this._map.on("mouseleave", layer, () => { this._map.getCanvas().style.cursor = ""; });
    }
  }

  // Tear the MapLibre map down (engine flip to floor, or disconnect).
  _teardownPowered() {
    this._glToken = (this._glToken || 0) + 1; // invalidate any in-flight draw
    if (this._map) { try { this._map.remove(); } catch {} this._map = null; }
    this._mlWired = false;
    const gl = this.shadowRoot && this.shadowRoot.querySelector(".gl");
    if (gl) gl.innerHTML = "";
  }

  // Lit lifecycle: the shell just (re)rendered — (re)wire pan/zoom/select. Old
  // listeners die with the replaced nodes (unsafeHTML rebuilds the markup).
  updated() {
    const root = this.shadowRoot;
    const stage = root.querySelector(".stage");
    const svg = root.querySelector("svg");
    const tip = root.querySelector("#tip");
    if (!svg) return;

    // tier dispatch: the floor SVG is ALWAYS wired below (the guaranteed render +
    // instant fallback). When MapLibre is chosen we additionally draw it into the
    // .gl host (CSS hides the floor svg once it has a child). unsafeHTML rebuilt
    // the .gl node each render, so re-mount the powered tier here.
    const choice = this._tierChoice();
    if (choice === "floor") {
      this._teardownPowered();
    } else if (this._features.length) {
      this._teardownPowered();   // fresh .gl node → drop old map, redraw into new
      this._drawPowered();
    }

    // pan (drag)
    let dragging = false, sx = 0, sy = 0, ox = 0, oy = 0;
    const VB = 1000;
    svg.addEventListener("pointerdown", (e) => {
      dragging = true; stage.classList.add("dragging");
      sx = e.clientX; sy = e.clientY; ox = this._view.x; oy = this._view.y;
      svg.setPointerCapture?.(e.pointerId);
    });
    svg.addEventListener("pointermove", (e) => {
      if (!dragging) return;
      const rect = svg.getBoundingClientRect();
      this._view.x = ox + (e.clientX - sx) / (rect.width || 1);
      this._view.y = oy + (e.clientY - sy) / (rect.height || 1) * (rect.height / rect.width);
      this._applyTransform();
    });
    const end = () => { dragging = false; stage.classList.remove("dragging"); };
    svg.addEventListener("pointerup", end);
    svg.addEventListener("pointerleave", end);

    // zoom (wheel + buttons), centered on cursor
    svg.addEventListener("wheel", (e) => {
      e.preventDefault();
      this._zoomAt(e.deltaY < 0 ? 1.18 : 1 / 1.18, e, svg);
    }, { passive: false });
    root.querySelectorAll(".zoom button").forEach((b) =>
      b.addEventListener("click", () => this._zoomCenter(b.dataset.z === "in" ? 1.4 : 1 / 1.4)));

    // feature select + tooltip
    root.querySelectorAll("[data-i]").forEach((el) => {
      const i = +el.getAttribute("data-i");
      el.addEventListener("click", (e) => { e.stopPropagation(); this._select(i); });
      el.addEventListener("pointerenter", (e) => this._showTip(i, e, tip, svg));
      el.addEventListener("pointermove", (e) => this._moveTip(e, tip, svg));
      el.addEventListener("pointerleave", () => tip && tip.classList.remove("show"));
    });
    svg.addEventListener("click", () => this._select(null));
  }

  _applyTransform() {
    const { k, x, y } = this._view, VB = 1000;
    const t = `translate(${x * VB} ${y * VB}) scale(${k})`;
    this.shadowRoot.querySelectorAll("svg > g").forEach((g) => g.setAttribute("transform", t));
  }

  _zoomCenter(factor) {
    const k0 = this._view.k, k1 = clamp(k0 * factor, 0.5, 60);
    // zoom about plane-center of current view
    const cx = (0.5 - this._view.x) / k0, cy = (0.5 - this._view.y) / k0;
    this._view.k = k1;
    this._view.x = 0.5 - cx * k1;
    this._view.y = 0.5 - cy * k1;
    this.requestUpdate(); // re-render so marker radii rescale crisply
  }

  _zoomAt(factor, e, svg) {
    const rect = svg.getBoundingClientRect();
    const fx = (e.clientX - rect.left) / (rect.width || 1);
    const fy = (e.clientY - rect.top) / (rect.height || 1);
    const k0 = this._view.k, k1 = clamp(k0 * factor, 0.5, 60);
    const px = (fx - this._view.x) / k0, py = (fy - this._view.y) / k0;
    this._view.k = k1;
    this._view.x = fx - px * k1;
    this._view.y = fy - py * k1;
    this.requestUpdate();
  }

  _select(i) {
    this._sel = i;
    const f = i == null ? null : this._features.find((ft) => ft.i === i);
    this._applySelectionAttrs();
    if (f) this._emit("work-feature-select", { feature: f.row, index: i });
  }

  _applySelectionAttrs() {
    this.shadowRoot.querySelectorAll("[data-i]").forEach((el) => {
      if (+el.getAttribute("data-i") === this._sel) el.setAttribute("aria-selected", "true");
      else el.removeAttribute("aria-selected");
    });
  }

  _tipText(f) {
    if (!f) return "";
    const lab = f.label != null ? String(f.label)
      : f.row && (f.row[this.attr("label")] ?? f.row[this.attr("key")]);
    const v = f.v != null && !Number.isNaN(+f.v) ? `${this.attr("value") || "value"}: ${fmtNum(f.v)}` : "";
    return [lab, v].filter(Boolean).join(" · ") || `#${f.i}`;
  }

  _showTip(i, e, tip, svg) {
    const f = this._features.find((ft) => ft.i === i);
    if (!tip || !f) return;
    tip.textContent = this._tipText(f);
    tip.classList.add("show");
    this._moveTip(e, tip, svg);
  }
  _moveTip(e, tip, svg) {
    if (!tip || !tip.classList.contains("show")) return;
    const rect = svg.getBoundingClientRect();
    tip.style.left = `${e.clientX - rect.left}px`;
    tip.style.top = `${e.clientY - rect.top}px`;
  }

  _emit(name, detail) {
    this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }));
  }
}

// ── helpers (token-unaware) ────────────────────────────────────────────────────
function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }
function colIdx(r, name) { return name == null ? -1 : r.columns.indexOf(name); }
function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
function esc(s) {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}
function fmtNum(v) {
  if (v == null || Number.isNaN(+v)) return "";
  const n = +v;
  return Number.isInteger(n) ? n.toLocaleString() : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
}
function safeJson(s) { try { return JSON.parse(s); } catch { return null; } }

/** GeoJSON geometry -> array of rings, each ring an array of projected [x,y]. */
function geometryToRings(geom, proj) {
  if (!geom) return [];
  const ringsOf = (coords) => coords.map((ring) => ring.map(([lon, lat]) => project(lon, lat, proj)));
  if (geom.type === "Polygon") return ringsOf(geom.coordinates);
  if (geom.type === "MultiPolygon") return geom.coordinates.flatMap((poly) => ringsOf(poly));
  return [];
}

define("work-map", WbMap);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// workponents · data — THE shared query/result contract.
//
// This is the single data interface every data surface consumes:
// `tables`, `data-viz`, `maps`, `records`, and `search` all talk to ONE engine
// through this shape. It is framework-agnostic, zero-dependency, and TOKEN-UNAWARE
// (pure data — no CSS, no DOM). An element imports `getEngine()` from ./engine.js,
// registers its source once, and runs queries; the element owns render + theme.
//
// The engine is SQLite, resolved by the Host per context: the workbook's native
// SQLite VFS over the runtime (Dock `vfs-query`), in-page sqlite-wasm when static,
// or the in-JS subset floor. One SQL dialect everywhere — write SQLite SQL.
//
// ─────────────────────────────────────────────────────────────────────────────
// Result shape — every query (runtime VFS, in-page sqlite-wasm, or the in-JS
// floor) returns EXACTLY this. Every surface must code against this and nothing
// else:
//
//   /** @typedef {Object} WbQueryResult
//    *  @property {string[]}    columns  ordered column names
//    *  @property {any[][]}     rows     row-major; rows[i][j] is column j of row i
//    *  @property {WbColType[]} types    per-column logical type (columns.length)
//    *  @property {number}      rowCount rows.length (convenience)
//    *  @property {string}      [engine] which tier answered: runtime|sqlite-wasm|memory
//    *  @property {string}      [sql]    the SQL actually executed (debug)
//    */
//
//   WbColType ∈ "number" | "integer" | "string" | "boolean" | "date" | "json"
//
// Engine surface (engine.js implements this; every surface reuses it verbatim):
//
//   query(sql: string, params?: any[]) -> Promise<WbQueryResult>
//   register(name: string, source: WbSource) -> Promise<void>   // makes a table
//   whenRegistered(name: string) -> Promise<void>  // await before querying it
//   available() -> boolean      // is a real SQLite tier reachable (vs the floor)
//   writable() -> boolean       // are writes durable (runtime VFS) vs local/none
//   provider() -> string        // "runtime" | "sqlite-wasm" | "memory"
//
// Source registration — "a workbook's data IS its source" (for INLINE data; a
// real workbook's tables already live in its SQLite VFS, no registration). One of:
//
//   { rows: object[] }                         inline array of row objects
//   { columns: string[], rows: any[][] }       columnar inline
//   { csv: string }                            CSV text (header row)
//   { json: string | object[] }                JSON text or parsed array
//   { url: string, format?: "csv"|"json" }     fetched (browser/runtime)
//
// `params` use positional `?` placeholders (SQLite style). All tiers bind the same.
// ─────────────────────────────────────────────────────────────────────────────

/** Normalize any WbSource into { columns, rows(object[]) } for registration. */
export function normalizeSource(src) {
  if (!src || typeof src !== "object") throw new Error("wb-data: source must be an object");
  if (Array.isArray(src.rows) && src.columns) {
    // columnar inline → objects
    const cols = src.columns;
    return { columns: cols, rows: src.rows.map((r) => objFromRow(cols, r)) };
  }
  if (Array.isArray(src.rows)) {
    const cols = inferColumns(src.rows);
    return { columns: cols, rows: src.rows };
  }
  if (typeof src.csv === "string") return parseCsv(src.csv);
  if (src.json != null) {
    const arr = typeof src.json === "string" ? JSON.parse(src.json) : src.json;
    if (!Array.isArray(arr)) throw new Error("wb-data: json source must be an array of rows");
    return { columns: inferColumns(arr), rows: arr };
  }
  throw new Error("wb-data: unsupported source (need rows|columns+rows|csv|json|url|arrow)");
}

function objFromRow(cols, row) {
  if (Array.isArray(row)) {
    const o = {};
    cols.forEach((c, i) => (o[c] = row[i]));
    return o;
  }
  return row;
}

function inferColumns(rows) {
  const seen = new Set();
  const cols = [];
  for (const r of rows) for (const k of Object.keys(r)) if (!seen.has(k)) { seen.add(k); cols.push(k); }
  return cols;
}

/** Minimal RFC-4180-ish CSV parse (quotes, escaped quotes, commas, newlines). */
export function parseCsv(text) {
  const rows = [];
  let field = "", row = [], inQ = false;
  const t = text.replace(/\r\n?/g, "\n");
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (inQ) {
      if (c === '"') { if (t[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n") { row.push(field); rows.push(row); field = ""; row = []; }
    else field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  const filtered = rows.filter((r) => r.length > 1 || (r.length === 1 && r[0] !== ""));
  if (!filtered.length) return { columns: [], rows: [] };
  const columns = filtered[0].map((h) => h.trim());
  const out = filtered.slice(1).map((r) => {
    const o = {};
    columns.forEach((col, i) => (o[col] = coerce(r[i])));
    return o;
  });
  return { columns, rows: out };
}

/** Coerce a CSV/string cell to number/boolean where it is unambiguous. */
export function coerce(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (s === "") return null;
  if (s === "true") return true;
  if (s === "false") return false;
  if (/^-?\d+$/.test(s)) return parseInt(s, 10);
  if (/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
  return s;
}

/** Infer a WbColType from a sample of column values. */
export function inferType(values) {
  let n = 0, allInt = true, num = 0, bool = 0, total = 0;
  for (const v of values) {
    if (v == null) continue;
    total++;
    if (typeof v === "boolean") { bool++; continue; }
    if (typeof v === "number") { num++; if (!Number.isInteger(v)) allInt = false; continue; }
    n++;
  }
  if (total === 0) return "string";
  if (bool === total) return "boolean";
  if (num === total) return allInt ? "integer" : "number";
  return "string";
}

/** Build a WbQueryResult (columns/rows array-of-array/types) from row objects. */
export function resultFromObjects(rowObjs, columns, engine, sql) {
  const cols = columns || inferColumns(rowObjs);
  const rows = rowObjs.map((o) => cols.map((c) => o[c] ?? null));
  const types = cols.map((c, j) => inferType(rows.map((r) => r[j])));
  return { columns: cols, rows, types, rowCount: rows.length, engine, sql };
}

// workponents · data — the shared SQLite seam, behind the Host/Dock membrane.
//
// ONE engine, every data surface: `tables`, `data-viz`, `maps`, `records`, and
// `search` all import `getEngine()` and consume the contract in ./contract.js.
// A component NEVER picks where SQL runs — the Host resolves the tier by context
// (the platform-model `local | runtime` seam):
//
//   • runtime — a Workbooks runtime/nexus is connected. SQL routes over the Dock
//     to the workbook's native SQLite VFS (`exqlite`, server-side) via the
//     tenant query route. Data stays OUT of the client; writes are durable
//     (Litestream). This is "the unbundling" — the SQLite is docked out to the
//     nexus so it can be edited live.
//
//   • sqlite-wasm — no runtime. Real SQLite in the page (./sqlite-wasm.js): the
//     full dialect, byte-compatible with the runtime's `exqlite`. ~1MB, lazily
//     loaded once. "The SQLite layer in the workbook itself" — and, ahead, the
//     engine that opens a static workbook's hydrated embedded VFS (the single-HTML
//     format: VFS embedded as a compressed blob, hydrated via DecompressionStream).
//
//   • memory — last-resort floor (./memory-sql.js): the zero-dep in-JS SQL subset,
//     used only if sqlite-wasm can't load (offline, no CDN/self-host). It is a
//     SUBSET — not real SQLite — so sqlite-wasm is preferred whenever reachable.
//
// One SQLite dialect everywhere — native `exqlite` (runtime) and sqlite-wasm
// (browser) are two builds of the same engine, and a workbook's `.sqlite` is
// byte-portable between them. (DuckDB-wasm was removed: 34MB, a divergent dialect,
// and redundant — the workbook already ships SQLite.)

import { getHost } from "../core/host.js";
import { normalizeSource, resultFromObjects } from "./contract.js";
import { WasmSqlite, bootSqlite } from "./sqlite-wasm.js";
import { MemorySql } from "./memory-sql.js";

let _engine = null;

/** The shared engine singleton. Lazy, idempotent — call from any element. */
export function getEngine() {
  if (!_engine) _engine = new WbDataEngine();
  return _engine;
}

export class WbDataEngine {
  constructor() {
    this._host = getHost();
    this._sqlite = new WasmSqlite();  // real in-page SQLite (the local tier)
    this._memory = new MemorySql();   // zero-dep subset (load-failure floor only)
    this._sources = new Map();        // name -> normalized {columns, rows}
    this._provider = null;            // resolved on first use
    this._initPromise = null;
    this._regWaiters = new Map();     // name -> [resolve, ...] awaiting registration
    this._inflightRegs = new Set();   // register() promises still settling
    // Runtime SQL-over-VFS route (tenant SQLite via the Dock). `{tenant}` is
    // filled from the Host. Override per deploy if a runtime exposes another path.
    this.vfsQueryPath = "/api/library/{tenant}/query";
  }

  /**
   * Resolve once `name` is registered (and live on the active provider). Returns
   * immediately if it already is. Lets a declarative element with `src-name`
   * upgrade BEFORE the page calls register() without racing an unknown table —
   * the one ordering hazard shared by every surface.
   */
  whenRegistered(name) {
    if (this._sources.has(name)) return Promise.resolve();
    return new Promise((resolve) => {
      const arr = this._regWaiters.get(name) || [];
      arr.push(resolve);
      this._regWaiters.set(name, arr);
    });
  }

  /** Which tier answers: "runtime" (native VFS) | "sqlite-wasm" (local) | "memory". */
  provider() { return this._provider || (this._runtimeReady() ? "runtime" : "sqlite-wasm"); }

  /** Is a real SQLite engine reachable (runtime VFS or in-page sqlite-wasm)? */
  available() { return this._runtimeReady() || this._provider === "sqlite-wasm"; }

  /** Are writes durable (runtime/nexus `exqlite`) vs local/ephemeral or none? */
  writable() { return this._runtimeReady(); }

  _runtimeReady() {
    return this._host.available("vfs") || (this._host.runtimeUrl != null);
  }

  /** Register a named source so SQL can `FROM <name>`. Idempotent per name. */
  register(name, source) {
    // Track the in-flight promise so a query that references this table before
    // it lands (an element querying a table a SIBLING registers — no src-name
    // declared) can await it and retry, instead of failing "no such table".
    const p = this._doRegister(name, source);
    this._inflightRegs.add(p);
    p.finally(() => this._inflightRegs.delete(p));
    return p;
  }

  async _doRegister(name, source) {
    const norm = normalizeSource(source);
    this._sources.set(name, norm);
    // Seed the floor too, so a sqlite-wasm load failure still answers.
    this._memory.register(name, norm);
    await this._ensureProvider();
    if (this._provider === "runtime") {
      // Inline data pushed into a docked workbook (best-effort). Real workbook
      // tables already live in the VFS and need no registration.
      try {
        await this._host.request(this._regPath(), { body: { name, columns: norm.columns, rows: norm.rows } });
      } catch { /* runtime ingest best-effort; the floor still answers */ }
    } else if (this._provider === "sqlite-wasm") {
      await this._sqlite.register(name, norm);
    }
    // Now queryable on the active provider — release anyone awaiting this source.
    const waiters = this._regWaiters.get(name);
    if (waiters) { this._regWaiters.delete(name); for (const r of waiters) r(); }
  }

  /** query(sql, params?) -> Promise<WbQueryResult>. Every surface's one call. */
  async query(sql, params = []) {
    await this._ensureProvider();
    if (this._provider === "runtime") {
      try {
        const res = await this._host.request(this._queryPath(), { body: { sql, params } });
        const shaped = shapeRuntime(res, sql);
        if (shaped) return shaped;
      } catch { /* fall through to the local engine */ }
    }
    if (this._provider === "sqlite-wasm") {
      try {
        return await this._sqlite.query(sql, params);
      } catch (e) {
        // The table may simply not be registered YET (a sibling's register() is
        // mid-flight). Wait for pending registrations, then retry once.
        if (/no such table/i.test(String(e && e.message || e)) && this._inflightRegs.size) {
          await Promise.allSettled([...this._inflightRegs]);
          return this._sqlite.query(sql, params);
        }
        throw e;
      }
    }
    // Last-resort floor — the zero-dep in-JS subset (sqlite-wasm unavailable).
    return this._memory.query(sql, params);
  }

  // ── provider resolution ────────────────────────────────────────────────────
  async _ensureProvider() {
    if (this._provider) return;
    if (this._initPromise) return this._initPromise;
    // Runtime/nexus SQLite VFS when connected; else real in-page sqlite-wasm;
    // the in-JS subset only if sqlite-wasm can't load (offline, no CDN/self-host).
    this._initPromise = (async () => {
      if (this._runtimeReady()) { this._provider = "runtime"; return; }
      try {
        await bootSqlite();
        this._provider = "sqlite-wasm";
        // No re-registration here: every source arrives via register(), which
        // registers into the resolved provider after awaiting this boot. Looping
        // here too would double-register the same table concurrently (DROP/CREATE
        // racing a sibling's DDL) → transient "no such table".
      } catch {
        this._provider = "memory";
      }
    })();
    return this._initPromise;
  }

  _queryPath() {
    return this.vfsQueryPath.replace("{tenant}", encodeURIComponent(this._host.tenant || "local"));
  }
  _regPath() {
    return this._queryPath().replace(/\/query$/, "/register");
  }
}

/**
 * Shape a runtime SQL response into a WbQueryResult. Tolerant of the row shapes a
 * runtime may return ({columns, rows[][]} columnar, or an array of row-objects).
 * Returns null when unrecognized so query() falls back to the local floor.
 */
function shapeRuntime(res, sql) {
  if (!res) return null;
  if (Array.isArray(res)) {
    return resultFromObjects(res, res.length ? Object.keys(res[0]) : [], "runtime", sql);
  }
  if (Array.isArray(res.rows) && Array.isArray(res.columns)) {
    const types = res.types || res.columns.map(() => "string");
    return { columns: res.columns, rows: res.rows, types, rowCount: res.rows.length, engine: "runtime", sql };
  }
  if (Array.isArray(res.rows)) {
    const cols = res.columns || (res.rows.length ? Object.keys(res.rows[0]) : []);
    return resultFromObjects(res.rows, cols, "runtime", sql);
  }
  return null;
}

// workponents · data — the shared in-WASM data layer for the DuckDB trio.
//
// ONE engine, three surfaces. `tables`, `data-viz`, and `maps` all import from
// here and code against the contract in ./contract.js. Framework-agnostic,
// zero-dependency, token-unaware (pure data — no DOM, no CSS).
//
//   import { getEngine } from "../../data/index.js";
//   const db = getEngine();
//   await db.register("orders", { csv: "...." });        // a workbook's data IS its source
//   const res = await db.query("SELECT region, sum(rev) AS rev FROM orders GROUP BY region");
//   // res = { columns, rows (array-of-array), types, rowCount, engine }
//
// data-viz / maps consume the SAME shape: a chart reads res.rows[i][j] by
// res.columns; a geo-query reads lat/lon columns off the same result. Register
// once, query from every surface on the page (shared connection).
export { getEngine, WbDataEngine } from "./engine.js";
export {
  normalizeSource, parseCsv, coerce, inferType, resultFromObjects,
} from "./contract.js";
export { MemorySql } from "./memory-sql.js";

// workponents · data — the in-JS fallback engine (zero-dep, offline).
//
// A small SQL-subset interpreter so the surfaces compute REAL sort/filter/aggregate
// IN an engine even with no runtime tier AND no network (CDN blocked). It is the
// LAST RESORT behind ./engine.js — when the runtime VFS (Host) or in-page
// sqlite-wasm is reachable, real SQLite answers instead and this is never touched.
// It is a SUBSET (no CAST, joins, window fns) — not real SQLite; prefer the tiers.
//
// Supported (one flat table per query, the basic grid/chart/geo-query needs):
//   SELECT <proj> FROM <table>
//     [WHERE <cond> [AND/OR <cond>]...]
//     [GROUP BY <col>[, <col>]...]
//     [ORDER BY <col|alias> [ASC|DESC]][, ...]
//     [LIMIT n [OFFSET m]]
//   proj: *, col, col AS alias, AGG(col) [AS alias], COUNT(*)
//   agg:  COUNT | SUM | AVG | MIN | MAX
//   cond: col OP value   OP ∈ = != <> < <= > >= LIKE   value: number|'str'|?
//   ? params bind positionally (SQLite style).
//
// Deliberately small. For anything beyond this, a real engine is required — the
// element degrades by surfacing the engine name so authors know which tier ran.

import { resultFromObjects } from "./contract.js";

const AGG_RE = /^(count|sum|avg|min|max)\s*\(\s*(\*|[\w."]+)\s*\)$/i;

export class MemorySql {
  constructor() {
    /** @type {Map<string,{columns:string[],rows:object[]}>} */
    this.tables = new Map();
  }

  register(name, normalized) {
    this.tables.set(name, normalized);
  }

  /** query(sql, params?) -> WbQueryResult */
  query(sql, params = []) {
    const q = parse(sql);
    const tbl = this.tables.get(q.from);
    if (!tbl) throw new Error(`wb-data(memory): unknown table "${q.from}"`);
    let rows = tbl.rows.slice();
    const binds = params.slice();

    // WHERE
    if (q.where.length) {
      rows = rows.filter((r) => evalWhere(r, q.where, binds.slice()));
    }

    let out;
    const hasAgg = q.select.some((s) => s.agg);
    if (q.groupBy.length || hasAgg) {
      out = aggregate(rows, q);
    } else {
      out = rows.map((r) => projectRow(r, q.select, tbl.columns));
    }

    // ORDER BY (by output alias/name)
    for (let i = q.orderBy.length - 1; i >= 0; i--) {
      const { key, dir } = q.orderBy[i];
      out.sort((a, b) => cmp(a[key], b[key]) * (dir === "desc" ? -1 : 1));
    }

    // LIMIT / OFFSET
    if (q.offset) out = out.slice(q.offset);
    if (q.limit != null) out = out.slice(0, q.limit);

    const columns = q.star ? (out[0] ? Object.keys(out[0]) : tbl.columns) : q.select.map((s) => s.alias);
    return resultFromObjects(out, columns, "memory", sql);
  }
}

function projectRow(r, select, allCols) {
  const o = {};
  for (const s of select) {
    if (s.star) { for (const c of allCols) o[c] = r[c]; continue; }
    o[s.alias] = r[s.col];
  }
  return o;
}

function aggregate(rows, q) {
  const groupCols = q.groupBy;
  const groups = new Map();
  for (const r of rows) {
    const key = groupCols.map((c) => r[c]).join("");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }
  if (!groups.size && !groupCols.length) groups.set("", []); // global agg over empty set
  const out = [];
  for (const bucket of groups.values()) {
    const o = {};
    for (const s of q.select) {
      if (s.star && !s.agg) { for (const c of groupCols) o[c] = bucket[0]?.[c]; continue; }
      if (s.agg) o[s.alias] = applyAgg(s.agg, s.col, bucket);
      else o[s.alias] = bucket[0]?.[s.col] ?? null; // grouping column
    }
    out.push(o);
  }
  return out;
}

function applyAgg(agg, col, bucket) {
  if (agg === "count") return col === "*" ? bucket.length : bucket.filter((r) => r[col] != null).length;
  const nums = bucket.map((r) => Number(r[col])).filter((n) => !Number.isNaN(n));
  if (!nums.length) return null;
  if (agg === "sum") return nums.reduce((a, b) => a + b, 0);
  if (agg === "avg") return nums.reduce((a, b) => a + b, 0) / nums.length;
  if (agg === "min") return Math.min(...nums);
  if (agg === "max") return Math.max(...nums);
  return null;
}

function cmp(a, b) {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), undefined, { numeric: true });
}

function evalWhere(row, clauses, binds) {
  // clauses: [cond, {bool}, cond, ...] — left-to-right, AND/OR (no precedence/parens)
  let acc = null, op = "and";
  for (const node of clauses) {
    if (node.bool) { op = node.bool; continue; }
    const v = testCond(row, node, binds);
    acc = acc == null ? v : op === "and" ? acc && v : acc || v;
  }
  return acc == null ? true : acc;
}

function testCond(row, c, binds) {
  const lhs = row[c.col];
  const rhs = c.param ? binds.shift() : c.value;
  switch (c.op) {
    case "=": return looseEq(lhs, rhs);
    case "!=": case "<>": return !looseEq(lhs, rhs);
    case "<": return num(lhs) < num(rhs);
    case "<=": return num(lhs) <= num(rhs);
    case ">": return num(lhs) > num(rhs);
    case ">=": return num(lhs) >= num(rhs);
    case "like": return likeMatch(String(lhs ?? ""), String(rhs ?? ""));
    default: return false;
  }
}

function looseEq(a, b) {
  if (typeof a === "number" || typeof b === "number") return num(a) === num(b);
  return String(a) === String(b);
}
function num(v) { const n = Number(v); return Number.isNaN(n) ? v : n; }
function likeMatch(s, pat) {
  const re = new RegExp("^" + pat.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/%/g, ".*").replace(/_/g, ".") + "$", "i");
  return re.test(s);
}

// ── parser ───────────────────────────────────────────────────────────────────
function parse(sql) {
  const s = sql.trim().replace(/;$/, "");
  const m = /^select\s+(.+?)\s+from\s+([\w."]+)(.*)$/is.exec(s);
  if (!m) throw new Error("wb-data(memory): only SELECT … FROM … is supported");
  const projRaw = m[1], from = unquote(m[2]);
  let rest = m[3] || "";

  const where = [], groupBy = [], orderBy = [];
  let limit = null, offset = 0;

  const limitM = /\blimit\s+(\d+)(?:\s+offset\s+(\d+))?/i.exec(rest);
  if (limitM) { limit = +limitM[1]; offset = limitM[2] ? +limitM[2] : 0; rest = rest.replace(limitM[0], ""); }
  const offM = /\boffset\s+(\d+)/i.exec(rest);
  if (offM) { offset = +offM[1]; rest = rest.replace(offM[0], ""); }

  const orderM = /\border\s+by\s+(.+?)(?=\bgroup\s+by\b|$)/is.exec(rest);
  if (orderM) {
    rest = rest.replace(orderM[0], "");
    for (const part of orderM[1].split(",")) {
      const [, key, dir] = /^\s*([\w."]+)\s*(asc|desc)?\s*$/i.exec(part) || [];
      if (key) orderBy.push({ key: unquote(key), dir: (dir || "asc").toLowerCase() });
    }
  }
  const groupM = /\bgroup\s+by\s+(.+?)(?=\border\s+by\b|$)/is.exec(rest);
  if (groupM) {
    rest = rest.replace(groupM[0], "");
    for (const p of groupM[1].split(",")) groupBy.push(unquote(p.trim()));
  }
  const whereM = /\bwhere\s+(.+)$/is.exec(rest);
  if (whereM) parseWhere(whereM[1].trim(), where);

  const select = [];
  let star = false;
  for (const raw of splitTop(projRaw)) {
    const item = raw.trim();
    if (item === "*") { select.push({ star: true }); star = true; continue; }
    const asM = /\s+as\s+([\w]+)\s*$/i.exec(item);
    const alias = asM ? asM[1] : null;
    const expr = asM ? item.slice(0, asM.index).trim() : item;
    const aggM = AGG_RE.exec(expr);
    if (aggM) {
      const agg = aggM[1].toLowerCase();
      const col = aggM[2] === "*" ? "*" : unquote(aggM[2]);
      select.push({ agg, col, alias: alias || `${agg}_${col === "*" ? "all" : col}` });
    } else {
      const col = unquote(expr);
      select.push({ col, alias: alias || col });
    }
  }
  return { select, star, from, where, groupBy, orderBy, limit, offset };
}

function parseWhere(str, out) {
  // split on top-level AND/OR (no parens support — flat list)
  const parts = str.split(/\s+(and|or)\s+/i);
  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 1) { out.push({ bool: parts[i].toLowerCase() }); continue; }
    // accept the floor's `CAST(col AS TYPE)` coercion (used by work-search/-command
    // so non-string columns LIKE-match) — the memory tier is the floor's own offline
    // engine, so it must run the floor's own query. Reduce the cast to the column;
    // the JS comparison is type-agnostic (String() coerces), so the cast is a no-op.
    const cast = /^\s*CAST\s*\(\s*([\w."]+)\s+AS\s+\w+\s*\)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    const m = cast || /^\s*([\w."]+)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    if (!m) throw new Error(`wb-data(memory): bad WHERE clause "${parts[i]}"`);
    const col = unquote(m[1]), op = m[2].toLowerCase();
    let value = m[3].trim(), param = false;
    if (value === "?") param = true;
    else if (/^'.*'$/.test(value)) value = value.slice(1, -1).replace(/''/g, "'");
    else if (/^-?\d*\.?\d+$/.test(value)) value = parseFloat(value);
    out.push({ col, op, value, param });
  }
}

function splitTop(s) {
  // split on commas not inside parentheses
  const out = []; let depth = 0, cur = "";
  for (const c of s) {
    if (c === "(") depth++;
    else if (c === ")") depth--;
    if (c === "," && depth === 0) { out.push(cur); cur = ""; } else cur += c;
  }
  if (cur.trim()) out.push(cur);
  return out;
}

function unquote(s) { return String(s).trim().replace(/^"(.*)"$/, "$1"); }

// workponents · data — the browser-local SQLite tier (sqlite-wasm).
//
// Real SQLite, in the page: the full dialect, byte-compatible with the runtime's
// native `exqlite` VFS. This is "the SQLite layer in the workbook itself" for the
// static / no-runtime case — and, ahead, the engine that opens a workbook's
// hydrated embedded VFS (the single-HTML format). ~1MB, lazily loaded once.
//
// Override the asset base via `window.__WB_SQLITE_WASM__` (a base URL ending in
// `/`) to self-host instead of the CDN — e.g. ship the wasm with the workbook.
import { inferType } from "./contract.js";

const DEFAULT_BASE = "https://cdn.jsdelivr.net/npm/@sqlite.org/sqlite-wasm@3.50.1-build1/";
let _boot = null;

/** Boot sqlite-wasm once (idempotent). Resolves { sqlite3, db } (in-memory db). */
export function bootSqlite() {
  if (_boot) return _boot;
  _boot = (async () => {
    if (typeof window === "undefined") throw new Error("sqlite-wasm needs a browser");
    const base = window.__WB_SQLITE_WASM__ || DEFAULT_BASE;
    const mod = await import(/* @vite-ignore */ base + "index.mjs");
    const sqlite3 = await mod.default({ locateFile: (f) => base + "sqlite-wasm/jswasm/" + f });
    return { sqlite3, db: new sqlite3.oo1.DB(":memory:", "c") };
  })();
  return _boot;
}

/** A WbDataEngine tier backed by real in-page SQLite. Same contract as the floor. */
export class WasmSqlite {
  /** Register a normalized source ({columns, rows: object[]}) as a table. */
  async register(name, norm) {
    const { db } = await bootSqlite();
    const cols = norm.columns;
    db.exec(`DROP TABLE IF EXISTS ${ident(name)}`);
    db.exec(`CREATE TABLE ${ident(name)} (${cols.map(ident).join(", ")})`);
    if (!norm.rows.length) return;
    const stmt = db.prepare(`INSERT INTO ${ident(name)} VALUES (${cols.map(() => "?").join(", ")})`);
    try {
      db.exec("BEGIN");
      for (const row of norm.rows) {
        stmt.bind(cols.map((c) => sqlVal(row[c]))).step();
        stmt.reset(true);
      }
      db.exec("COMMIT");
    } finally {
      stmt.finalize();
    }
  }

  /** Run SQL → WbQueryResult (row-major arrays + per-column inferred types). */
  async query(sql, params = []) {
    const { db } = await bootSqlite();
    const columns = [];
    const rows = db.exec({
      sql,
      bind: params && params.length ? params : undefined,
      rowMode: "array",
      columnNames: columns,
      returnValue: "resultRows",
    });
    const types = columns.map((_c, j) => inferType(rows.map((r) => r[j])));
    return { columns, rows, types, rowCount: rows.length, engine: "sqlite-wasm", sql };
  }
}

function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }

/** Coerce a JS value to something sqlite-wasm can bind (no booleans/objects). */
function sqlVal(v) {
  if (v == null) return null;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number" || typeof v === "string" || typeof v === "bigint") return v;
  return JSON.stringify(v);
}

// maps · the POWERED tier — MapLibre GL behind the <work-map> floor.
//
// The floor (wb-map.js `_renderPoints`/`_renderHeat`/`_renderBubbles`/
// `_renderRegions`) is a zero-dependency SVG projection themed entirely from
// --work-*. This module is the powered alternative: it draws the SAME logical
// features (the SAME points / regions off the SAME engine query result) with a
// real MapLibre GL map — only the drawing/basemap changes, never the public API
// or the data path.
//
// Lazy-loaded from a CDN ESM at runtime (mirrors plot-tier.js / sqlite-wasm /
// wavelet): nothing is bundled, no dep is installed. `loadMaplibre()` is a
// single-flight import() resolving to the MapLibre namespace, overridable via
// `window.__WB_MAPLIBRE__` (tests / offline hosts inject their own). If the
// import fails (network-blocked — the gate's wasm/floor proof), the caller
// silently falls back to the floor SVG.
//
// BASEMAP via Host (gate-c, offline): we NEVER hardcode a CDN tile URL — that
// would fail the wasm/offline gate. With a Host that exposes the "tiles"
// capability (PMTiles / tile broker), real tile sources route through it. With
// NO Host, MapLibre renders a token-themed BLANK / vector style (background +
// the projected feature layers) — fully offline.
//
// THEMING (gate-a, token-leak): MapLibre ships its own default colors + injects
// its own <style>. We never let a literal leak — every color MapLibre paints
// (background/water/land/labels + the feature layers) is READ from the element's
// computed --work-* tokens (readTokens) and passed into the MapLibre style spec.
// Flip the theme → re-read tokens → re-apply paint → the map re-themes exactly
// like the floor.
//
// SCOPE (gate-b): MapLibre injects a global <style> into document.head by
// default. We force it SHADOW-scoped: before constructing the map we point
// MapLibre's stylesheet at our shadow root (it appends its CSS into the map
// container's root node when that node is a ShadowRoot), and we adopt MapLibre's
// stylesheet text into the element's own constructable stylesheet so nothing
// lands in document.head.

const MAPLIBRE_CDN = "https://esm.sh/maplibre-gl@4";
const MAPLIBRE_CSS_CDN = "https://esm.sh/maplibre-gl@4/dist/maplibre-gl.css";

let _mlPromise = null;
let _cssPromise = null;

/**
 * Single-flight lazy import of MapLibre GL. Resolves to the MapLibre namespace
 * (the module's default or `{ Map, ... }`). Overridable for tests / offline hosts
 * via `window.__WB_MAPLIBRE__`. Rejects when the chunk can't load — the caller
 * falls back to the floor.
 */
export function loadMaplibre() {
  const override = typeof window !== "undefined" && window.__WB_MAPLIBRE__;
  if (override) return Promise.resolve(override);
  if (!_mlPromise) {
    _mlPromise = import(/* @vite-ignore */ MAPLIBRE_CDN)
      .then((m) => m.default || m)
      .catch((e) => {
        _mlPromise = null; // allow a later retry
        throw e;
      });
  }
  return _mlPromise;
}

/**
 * Fetch MapLibre's stylesheet TEXT so we can adopt it shadow-scoped (gate-b) —
 * never a <link> in document.head. Best-effort: a failure just means the map
 * draws without MapLibre's control chrome CSS (the canvas itself is unaffected).
 * Skipped entirely when an override (shim) is active.
 */
function loadMaplibreCss() {
  if (typeof window !== "undefined" && window.__WB_MAPLIBRE__) return Promise.resolve("");
  if (!_cssPromise) {
    _cssPromise = fetch(MAPLIBRE_CSS_CDN).then((r) => (r.ok ? r.text() : "")).catch(() => "");
  }
  return _cssPromise;
}

// Read the resolved --work-* token VALUES off the element (computed style).
// MapLibre's style spec wants concrete colors, never `var(--work-*)` strings (it
// paints onto a WebGL canvas where the CSS cascade does not reach). Reading the
// computed value keeps MapLibre's paint locked to the active theme — flip the
// theme, re-read, re-apply → the map re-themes (the flip-delta gate passes).
export function readTokens(el) {
  const cs = getComputedStyle(el);
  const v = (name, fallback) => (cs.getPropertyValue(name).trim() || fallback);
  return {
    fg:        v("--work-fg", "#121316"),
    fgMuted:   v("--work-fg-muted", "rgba(18,19,22,0.6)"),
    fgSubtle:  v("--work-fg-subtle", "rgba(18,19,22,0.38)"),
    surface:   v("--work-surface", "#ffffff"),
    surfaceSoft: v("--work-surface-soft", "#efede6"),
    border:    v("--work-border", "rgba(18,19,22,0.13)"),
    borderStrong: v("--work-border-strong", "rgba(18,19,22,0.28)"),
    brand:     v("--work-brand", "#13d943"),
    brandSoft: v("--work-brand-soft", "rgba(19,217,67,0.13)"),
    font:      v("--work-font", "system-ui, sans-serif"),
  };
}

/**
 * Build the MapLibre style spec from tokens — a token-themed BLANK/vector style.
 * NO hardcoded CDN tile URL: the background + graticule/land come from token
 * colors; the actual data features are added as separate GeoJSON sources/layers
 * after the map loads. When `tileSource` is provided (resolved via Host) it is
 * spliced in UNDER the data layers as the real basemap.
 *
 * @param tk          readTokens(el)
 * @param tileSource  optional MapLibre source spec from the Host tile broker
 */
export function buildStyle(tk, tileSource) {
  const sources = {};
  const layers = [
    // token-themed "water" / page backdrop — the blank basemap floor.
    { id: "wb-bg", type: "background", paint: { "background-color": tk.surface } },
  ];
  if (tileSource) {
    sources["wb-tiles"] = tileSource;
    layers.push(
      tileSource.type === "raster"
        ? { id: "wb-basemap", type: "raster", source: "wb-tiles" }
        : { id: "wb-basemap", type: "fill", source: "wb-tiles", "source-layer": "land",
            paint: { "fill-color": tk.surfaceSoft, "fill-outline-color": tk.border } },
    );
  }
  // a sprite-less / glyph-less style — no external fetch (omit glyphs entirely;
  // MapLibre rejects an explicit `undefined`). We render no symbol/label layers,
  // so the missing glyph endpoint is never reached — fully offline-safe.
  return { version: 8, sources, layers };
}

/** Engine value range → [min,max] for token-driven scaling (mirrors floor). */
function valueRange(features) {
  let lo = Infinity, hi = -Infinity;
  for (const f of features) {
    if (f.v == null || Number.isNaN(+f.v)) continue;
    if (+f.v < lo) lo = +f.v;
    if (+f.v > hi) hi = +f.v;
  }
  if (!isFinite(lo)) return [0, 1];
  return [lo, hi];
}

/**
 * Convert the floor's projected feature list into a GeoJSON FeatureCollection in
 * lon/lat (MapLibre's native coordinate space). Points carry their original
 * lat/lon; regions are unprojected back to lon/lat from their plane rings via the
 * supplied `unproject`. The `_fi` property is the floor feature index `f.i` so
 * MapLibre selection maps back to the SAME work-feature-select contract.
 *
 * @param features  el._features (the floor's render-ready model)
 * @param unproject (x,y,kind)->[lon,lat]
 * @param projKind  "mercator" | "equirectangular"
 */
export function featuresToGeoJSON(features, unproject, projKind) {
  const out = { type: "FeatureCollection", features: [] };
  for (const f of features) {
    if (f.kind === "point") {
      out.features.push({
        type: "Feature",
        properties: { _fi: f.i, _v: f.v == null ? null : +f.v, _label: f.label == null ? null : String(f.label) },
        geometry: { type: "Point", coordinates: [f.lon, f.lat] },
      });
    } else if (f.kind === "region") {
      const rings = f.rings.map((rg) => rg.map(([x, y]) => unproject(x, y, projKind)));
      out.features.push({
        type: "Feature",
        properties: { _fi: f.i, _v: f.v == null ? null : +f.v },
        geometry: { type: "Polygon", coordinates: rings },
      });
    }
  }
  return out;
}

/**
 * Add the data layers (points / heat / choropleth) to a loaded MapLibre map,
 * styled from tokens. Returns the value range used (for the caller's legend).
 *
 * @param map      the MapLibre Map instance
 * @param mode     "points" | "heat" | "choropleth"
 * @param geojson  featuresToGeoJSON(...)
 * @param features el._features (for the value range)
 * @param tk       readTokens(el)
 */
export function addDataLayers(map, mode, geojson, features, tk) {
  const [lo, hi] = valueRange(features);
  const hasVal = hi > lo;
  if (map.getSource("wb-data")) {
    try { map.removeLayer("wb-points"); } catch {}
    try { map.removeLayer("wb-heat"); } catch {}
    try { map.removeLayer("wb-regions"); } catch {}
    try { map.removeLayer("wb-regions-line"); } catch {}
    map.getSource("wb-data").setData(geojson);
  } else {
    map.addSource("wb-data", { type: "geojson", data: geojson });
  }

  if (mode === "heat") {
    map.addLayer({
      id: "wb-heat", type: "heatmap", source: "wb-data",
      paint: {
        "heatmap-weight": hasVal
          ? ["interpolate", ["linear"], ["coalesce", ["get", "_v"], lo], lo, 0.2, hi, 1]
          : 0.6,
        "heatmap-radius": 32,
        "heatmap-opacity": 0.85,
        // token-driven ramp: transparent → brand-soft → brand.
        "heatmap-color": [
          "interpolate", ["linear"], ["heatmap-density"],
          0, "rgba(0,0,0,0)",
          0.4, tk.brandSoft,
          1, tk.brand,
        ],
      },
    });
  } else if (mode === "choropleth") {
    // regions (polygons) when present, else graduated bubbles at point coords.
    const hasPolys = geojson.features.some((f) => f.geometry.type === "Polygon");
    if (hasPolys) {
      map.addLayer({
        id: "wb-regions", type: "fill", source: "wb-data",
        filter: ["==", ["geometry-type"], "Polygon"],
        paint: {
          "fill-color": hasVal
            ? ["interpolate", ["linear"], ["coalesce", ["get", "_v"], lo], lo, tk.surfaceSoft, hi, tk.brand]
            : tk.surfaceSoft,
          "fill-opacity": 0.85,
          "fill-outline-color": tk.surface,
        },
      });
      map.addLayer({
        id: "wb-regions-line", type: "line", source: "wb-data",
        filter: ["==", ["geometry-type"], "Polygon"],
        paint: { "line-color": tk.border, "line-width": 1 },
      });
    } else {
      map.addLayer({
        id: "wb-points", type: "circle", source: "wb-data",
        filter: ["==", ["geometry-type"], "Point"],
        paint: {
          "circle-radius": hasVal
            ? ["interpolate", ["linear"], ["sqrt", ["max", ["coalesce", ["get", "_v"], lo], 0.0001]],
               Math.sqrt(Math.max(lo, 0.0001)), 6, Math.sqrt(Math.max(hi, 0.0001)), 26]
            : 8,
          "circle-color": hasVal
            ? ["interpolate", ["linear"], ["coalesce", ["get", "_v"], lo], lo, tk.surfaceSoft, hi, tk.brand]
            : tk.brand,
          "circle-opacity": 0.62,
          "circle-stroke-color": tk.surface,
          "circle-stroke-width": 1,
        },
      });
    }
  } else {
    // points
    map.addLayer({
      id: "wb-points", type: "circle", source: "wb-data",
      filter: ["==", ["geometry-type"], "Point"],
      paint: {
        "circle-radius": hasVal
          ? ["interpolate", ["linear"], ["sqrt", ["max", ["coalesce", ["get", "_v"], lo], 0.0001]],
             Math.sqrt(Math.max(lo, 0.0001)), 4, Math.sqrt(Math.max(hi, 0.0001)), 14]
          : 6,
        "circle-color": tk.brand,
        "circle-opacity": 0.82,
        "circle-stroke-color": tk.surface,
        "circle-stroke-width": 1.2,
      },
    });
  }
  return [lo, hi];
}

/**
 * Re-apply token colors to an existing map's layers (theme flip) without
 * rebuilding the map. Reads paint props that exist; missing layers are skipped.
 */
export function applyTheme(map, mode, tk) {
  if (!map || !map.getLayer) return;
  const set = (layer, prop, val) => { try { if (map.getLayer(layer)) map.setPaintProperty(layer, prop, val); } catch {} };
  set("wb-bg", "background-color", tk.surface);
  set("wb-points", "circle-stroke-color", tk.surface);
  set("wb-regions-line", "line-color", tk.border);
  // the value-driven ramps already encode token colors at build time; for a flip
  // we rebuild the data layers from the caller (re-read tokens), so this covers
  // the static (non-value) paints that don't get rebuilt.
}

export { MAPLIBRE_CDN, loadMaplibreCss };

// workponents · maps — projections (token-unaware, zero-dep, pure math).
//
// A map is a SPATIAL VIEW OVER A QUERY. The element gets lat/lon off the query
// result; these functions turn (lon, lat) into normalized [0..1] plane coords so
// the view can place them in an abstract themed projection — NO tile provider,
// NO network. The same normalized coords drive pan/zoom (a viewBox transform).
//
// Two projections, both standalone:
//   equirectangular — lon/lat map linearly to x/y (plate carrée). Cheap, global.
//   mercator        — Web Mercator (the basemap projection); matches tile pixels
//                     if/when a Host tile layer is wired, so points stay aligned.

const DEG = Math.PI / 180;
const MERC_MAX_LAT = 85.05112878; // Web Mercator clamp (poles -> infinity)

/** Project [lon, lat] -> normalized [x, y] in [0..1] (y down, like SVG). */
export function project(lon, lat, kind = "mercator") {
  lon = clamp(+lon, -180, 180);
  lat = +lat;
  if (kind === "equirectangular") {
    return [(lon + 180) / 360, (90 - clamp(lat, -90, 90)) / 180];
  }
  // mercator
  lat = clamp(lat, -MERC_MAX_LAT, MERC_MAX_LAT);
  const x = (lon + 180) / 360;
  const s = Math.sin(lat * DEG);
  const y = 0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI);
  return [x, clamp(y, 0, 1)];
}

/** Inverse — normalized [x,y] back to [lon, lat] (for hit-tests / fit). */
export function unproject(x, y, kind = "mercator") {
  if (kind === "equirectangular") {
    return [x * 360 - 180, 90 - y * 180];
  }
  const lon = x * 360 - 180;
  const n = Math.PI - 2 * Math.PI * y;
  const lat = (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
  return [lon, lat];
}

/** Bounding box (in normalized plane coords) of a set of [lon,lat] points. */
export function bounds(points, kind) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [lon, lat] of points) {
    const [x, y] = project(lon, lat, kind);
    if (x < minX) minX = x; if (y < minY) minY = y;
    if (x > maxX) maxX = x; if (y > maxY) maxY = y;
  }
  if (!isFinite(minX)) return { minX: 0, minY: 0, maxX: 1, maxY: 1 };
  return { minX, minY, maxX, maxY };
}

function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
